from fractions import Fraction as F
base=['24','/','3','-','4','*','2','+','6','*','5','+','12']
def ev(a,b):
    t=[ (b if x==a else a if x==b else x) for x in base]
    return eval(''.join(t))
opts={'A':('4','3'),'B':('5','4'),'C':('3','2'),'D':('24','12')}
ok=[k for k,(a,b) in opts.items() if abs(ev(a,b)-50)<1e-9]
assert ok==['D']

opts={"A":(4,3),"B":(5,4),"C":(3,2),"D":(24,12)}
base=[24,3,4,2,6,5,12]
def ev(v):
    a,b,c,d,e,f,g=v
    return a/b-c*d+e*f+g
res={}
for k,(p,q) in opts.items():
    v=[q if t==p else p if t==q else t for t in base]
    res[k]=ev(v)
assert res["D"]==50
for k in "ABC": assert res[k]!=50

