import math
opts={"A":(64,78,99),"B":(48,65,82),"C":(27,38,51),"D":(79,98,119)}
def ok(t):
    r=[math.isqrt(x+2) for x in t]
    return all(a*a==x+2 for a,x in zip(r,t)) and r[1]==r[0]+1 and r[2]==r[1]+1
assert [k for k,v in opts.items() if ok(v)]==["D"]

